code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    frames = []
    for top in range(h - 2):
        for bottom in range(top + 2, h):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    if (all(grid[top][c] == 2 and grid[bottom][c] == 2 for c in range(left, right + 1))
                        and all(grid[r][left] == 2 and grid[r][right] == 2 for r in range(top, bottom + 1))):
                        frames.append((top, bottom, left, right))
    for top, bottom, left, right in frames:
        for r in range(top + 1, bottom):
            for c in range(left + 1, right):
                if out[r][c] == 0:
                    out[r][c] = 8
    return out
'''
